package gov.takx.api.systemmessage;

import gov.takx.api.logging.SystemLogLevel;

import java.util.List;

/**
 * Contract for the System Message Manager.  System messages are generated by calling the
 * {@link #addMessage(SystemMessage)} method, or within the application when messages of certain levels are
 * recorded in the standard logging operations (using log4j).  Anything with a level of
 * {@link SystemLogLevel#SYSTEM_WARN} or greater will result in a system message being recorded.
 * <p/>
 * System messages will be logged and made visible to the user. The system tracks when the user views the system
 * message log.  Each time the log is viewed, the "outstanding" message counts are reset to 0.  The user will be
 * informed of the number and level (severity) of the highest level of outstanding messages.  So, if the system
 * has 4 INFO, 2 WARNING, and 3 ERROR outstanding messages, the user will be informed that the highest level
 * is ERROR, and there are a total of 9 outstanding messages.
 * <p/>
 * Once the System Message Log is viewed, these counts will be reset.
 * <p/>
 * To receive notification of new messages, use {@link #addSystemMessageManagerListener(ISystemMessageManagerListener)}
 *
 * @since 1.43
 */
public interface ISystemMessageManager extends ISystemMessageLogger
{
    /**
     * Add a system message.  Update the highest outstanding level and count.
     *
     * @param message Message to add
     * @see #getHighestOutstandingLevel()
     * @see #getOutstandingCount()
     */
    void addMessage(SystemMessage message);

    /**
     * Reset the outstanding message count to 0.
     */
    void resetOutstandingCount();

    /**
     * Get the level of the highest outstanding message.  This may not be the exact level of that message,
     * it will be a canonical level.
     *
     * @return Highest level with outstanding messages, {@link SystemLogLevel#SYSTEM_ALL} if there are no outstanding messages.
     */
    SystemLogLevel getHighestOutstandingLevel();

    /**
     * @return Count of outstanding messages
     */
    int getOutstandingCount();

    /**
     * Take all the messages that have been recorded since inception, then clear that collection.  This is used
     * to accumulate messages prior to the creation of the UI view element that needs to display them.
     *
     * @return List of all messages
     */
    List<SystemMessage> takePendingMessages();

    /**
     * Add a listener for system message manager events.
     *
     * @param listener Listener to add
     */
    void addSystemMessageManagerListener(ISystemMessageManagerListener listener);

    /**
     * Remove a system message manager listener.
     *
     * @param listener Listener to add
     */
    void removeSystemMessageManagerListener(ISystemMessageManagerListener listener);
}
